package edu.portal.service;
import edu.portal.model.*; import org.junit.jupiter.api.Test; import java.time.LocalDate; import java.util.Set; import static org.junit.jupiter.api.Assertions.*;
class ApplicationRulesTest { @Test void selectionMustFollowShortlisting(){assertThrows(InvalidStatusTransitionException.class,()->new ApplicationRules().validateTransition(ApplicationStatus.APPLIED,ApplicationStatus.SELECTED));} @Test void eligibleStudentPasses(){var s=new Student(1,"A",1,"B.Tech","Java",8,"a@x", "1");var v=new Vacancy(1,1,"Dev",7,"B.Tech",Set.of(1),"Pune",1,2,1,LocalDate.now().plusDays(1),true);assertDoesNotThrow(()->new EligibilityService().validate(s,v));} @Test void departmentFails(){var s=new Student(1,"A",2,"B.Tech","Java",8,"a@x","1");var v=new Vacancy(1,1,"Dev",7,"B.Tech",Set.of(1),"Pune",1,2,1,LocalDate.now().plusDays(1),true);assertThrows(NotEligibleException.class,()->new EligibilityService().validate(s,v));} }
